package nu.metacraft.nether_rifts.mob;

import de.tomalbrc.bil.core.model.Model;
import de.tomalbrc.bil.file.loader.BbModelLoader;
import nu.metacraft.nether_rifts.NetherRifts;

/**
 * The rift mobs' Blockbench models (generated by tools/gen_models.py into /model/nether_rifts/), loaded
 * once: BIL doesn't cache models, and they must exist before Polymer builds the resource pack.
 */
public final class RiftModels {

	public static final Model WAR_DRUMMER = load("war_drummer");
	public static final Model GHAST_BOMBARDIER = load("ghast_bombardier");
	public static final Model GHAST_HARNESS = load("ghast_harness");

	private RiftModels() {}

	/** Forces the models to load during mod init. */
	public static void init() {
	}

	private static Model load(String name) {
		return BbModelLoader.load(NetherRifts.getID(name));
	}
}
